            throw new IllegalArgumentException("Invalid URL: missing host");
        }

        // SSRF Protection: Validate resolved IP addresses to block internal/private networks
        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress address : addresses) {
                if (address.isLoopbackAddress() || 
                    address.isAnyLocalAddress() || 
                    address.isLinkLocalAddress() || 
                    address.isSiteLocalAddress()) {
                    throw new SecurityException("Access to internal or private network addresses is not allowed.");
                }
            }
        } catch (UnknownHostException e) {
            throw new IllegalArgumentException("Unknown host: " + host, e);
        }

        try {
            return restTemplate.getForObject(uri, String.class);
        } catch (RestClientException e) {
            throw new RuntimeException("Failed to fetch content from URL: " + url, e);
        }
    }
}
